mapper.select:
select sum(qty)
from (
         select count(1) as qty
         from ETR_ENTRUST
         where FINPROD_ID = #{finprodId}
           AND ENTRUST_DATE = to_date(#{iPlatformDate}, 'yyyy-MM-dd')
         union all
         select count(1) as qty
         from WFL_ETR_ENTRUST
         where FINPROD_ID = #{finprodId}
           AND ENTRUST_DATE = to_date(#{iPlatformDate}, 'yyyy-MM-dd')
     )

SELECT SECID finprodMarketId, SECNAME finprodAbbr
from INTERF_PAYHSRCSECINFO
WHERE SECNAME = #{search};

SELECT FINPROD_ID finprodMarketId, FINPROD_ABBR finprodAbbr
from FIN_PRODUCT
where FINPROD_ABBR = #{search};

SELECT sum(qty) FROM (
     select count(1) as qty
     from FIN_PRODUCT
     where FINPROD_MARKET_ID = #{finprodId}
     union all
     select count(1) as qty
     from INTERF_PAYHSRCSECINFO
     where SECID = #{finprodId}





    )
